style.css:
@-moz-document domain("openstax.org") {
/* ---------- Main ---------- */

html,
body {
    background: #0f1115 !important;
    color: #e6e6e6 !important;
}

/* Containers */

main,
article,
section,
div,
.content,
.page,
.book-content,
.book-page,
.os-content,
.chapter,
.cnx-eoc,
.cnx-body,
.cnx-archive,
.cnx-content {
    background: #12161d !important;
    color: #e6e6e6 !important;
}

/* ---------- Text ---------- */

p,
span,
li,
td,
th,
label,
blockquote {
    color: #dddddd !important;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    color: #ffffff !important;
}

/* ---------- Links ---------- */

a {
    color: #66b3ff !important;
}

a:hover {
    color: #9cd2ff !important;
}

/* ---------- Tables ---------- */

table {
    background: #181c24 !important;
    border-collapse: collapse !important;
}

table,
th,
td {
    border: 1px solid #303744 !important;
}

th {
    background: #212734 !important;
}

tr:nth-child(even) {
    background: #161b22 !important;
}

/* ---------- Code ---------- */

pre,
code {
    background: #1b2028 !important;
    color: #9ee37d !important;
    border-radius: 6px;
}

/* ---------- Blockquotes ---------- */

blockquote {
    background: #1a2028 !important;
    border-left: 4px solid #4ea3ff !important;
}

/* ---------- Images ---------- */

img,
svg,
video {
    background: transparent !important;
}

/* ---------- Inputs ---------- */

input,
textarea,
select {
    background: #1a2028 !important;
    color: white !important;
    border: 1px solid #404854 !important;
}

/* ---------- Buttons ---------- */

button {
    background: #232a35 !important;
    color: white !important;
    border: 1px solid #454f5d !important;
}

button:hover {
    background: #2d3645 !important;
}

/* ---------- Navigation ---------- */

header,
nav,
footer,
aside {
    background: #12161d !important;
    color: white !important;
}

/* ---------- Cards ---------- */

.card,
.panel,
.box {
    background: #171c24 !important;
    border: 1px solid #2f3744 !important;
}

/* ---------- Math ---------- */

.MathJax,
.katex {
    color: #ffffff !important;
}

/* ---------- Selection ---------- */

::selection {
    background: #3d73d1;
    color: white;
}

/* ---------- Scrollbar ---------- */

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #111;
}

::-webkit-scrollbar-thumb {
    background: #444;
}

::-webkit-scrollbar-thumb:hover {
    background: #666;
}
}
